export const chapter1RemainingFrench: Record<string, string[]> = {
  "ch1_p15": [
    "La Bourgeoisie a dépouillé de leur auréole toutes les professions qui passaient autrefois pour vénérables et sacrées.",
    "Le médecin, le juriste, le prêtre, le poète, l’homme de science, elle en a fait des salariés à ses gages."
  ],
  "ch1_p16": [
    "La Bourgeoisie a déchiré le voile de sentimentalité qui recouvrait les relations de famille et les a réduites à n'être que de simples rapports d'argent."
  ],
  "ch1_p17": [
    "La Bourgeoisie a démontré comment la brutale manifestation des forces au moyen âge, si admirée par la réaction, trouve son complément naturel dans la plus crasse paresse.",
    "C’est elle qui, la première, a fait la preuve de ce dont est capable l’activité humaine.",
    "Elle a créé de bien autres merveilles que les pyramides d’Égypte, les aqueducs romains et les cathédrales gothiques ; elle a conduit de bien autres expéditions que les migrations des peuples et les croisades."
  ],
  "ch1_p18": [
    "La Bourgeoisie n’existe qu’à la condition de révolutionner constamment les instruments de travail et, par conséquent, les rapports de production, c’est-à-dire l’ensemble des rapports sociaux.",
    "Le maintien de l’ancien mode de production était, au contraire, la première condition d’existence de toutes les classes industrielles antérieures.",
    "Ce bouleversement perpétuel de la production, cette instabilité constante de tout l’ordre social, cette agitation et ce mouvement perpétuels distinguent l’époque bourgeoise de toutes les époques antérieures.",
    "Tous les rapports sociaux, traditionnels et fixes, avec leur cortège de croyances et d’idées admises depuis des siècles, se dissolvent ; tout ce qui est nouveau vieillit avant d’avoir pu s’ossifier.",
    "Tout ce qui était solide et bien établi se volatilise, tout ce qui était sacré est profané, et les hommes sont enfin forcés d’envisager leurs conditions d’existence et leurs relations réciproques avec des yeux désabusés."
  ],
  "ch1_p19": [
    "Poussée par le besoin de débouchés toujours nouveaux, la Bourgeoisie envahit le globe entier.",
    "Il lui faut s’implanter partout, s’établir partout, créer partout des moyens de communication."
  ],
  "ch1_p20": [
    "Par l’exploitation du marché mondial, la bourgeoisie donne un caractère cosmopolite à la production et à la consommation de tous les pays.",
    "Au grand désespoir des réactionnaires, elle a enlevé à l’industrie sa base nationale.",
    "Les vieilles industries nationales ont été détruites et se détruisent encore tous les jours.",
    "Elles sont supplantées par de nouvelles industries, dont l’introduction devient une question de vie ou de mort pour toutes les nations civilisées, industries qui n’emploient plus des matières premières indigènes, mais des matières premières venues des régions les plus éloignées, et dont les produits se consomment non seulement dans le pays même, mais dans tous les coins du globe."
  ],
  "ch1_p21": [
    "À la place des anciens besoins, satisfaits par les produits du pays, naissent des besoins nouveaux, réclamant pour leur satisfaction les produits des contrées et des climats les plus lointains.",
    "À la place de l’ancien isolement des provinces et des nations se suffisant à elles-mêmes, se développent des relations universelles, une interdépendance universelle des nations.",
    "Et ce qui est vrai de la production matérielle ne l’est pas moins des productions de l’esprit.",
    "Et ce qui est vrai de la production matérielle ne l’est pas moins des productions de l’esprit.",
    "Et ce qui est vrai de la production matérielle ne l’est pas moins des productions de l’esprit."
  ],
  "ch1_p22": [
    "Par le rapide développement des instruments de production et des moyens de communication, la bourgeoisie entraîne dans le courant de la civilisation jusqu’aux nations les plus barbares.",
    "Le bon marché de ses produits est la grosse artillerie qui bat en brèche toutes les murailles de Chine et fait capituler les barbares les plus obstinément hostiles aux étrangers.",
    "Sous peine de mort, elle force toutes les nations à adopter le mode de production bourgeois.",
    "Elle les force à introduire chez elles la prétendue civilisation, c’est-à-dire à devenir bourgeoises."
  ],
  "ch1_p23": [
    "La Bourgeoisie a soumis la campagne à la ville.",
    "Elle a créé d’énormes cités ; elle a prodigieusement augmenté le chiffre des populations urbaines par rapport aux populations rurales, et, par là, elle a arraché une partie notable de la population à l’abrutissement de la vie des champs.",
    "De même qu’elle a subordonné la campagne à la ville, les pays barbares ou demi-barbares aux pays civilisés, elle a subordonné les peuples de paysans aux peuples de bourgeois, l’Orient à l’Occident."
  ],
  "ch1_p24": [
    "La Bourgeoisie supprime de plus en plus l’éparpillement des moyens de production, de la propriété et de la population.",
    "Elle a aggloméré les populations, centralisé les moyens de production et concentré la propriété dans un petit nombre de mains.",
    "La conséquence fatale de ces changements a été la centralisation politique.",
    "Des provinces indépendantes, à peine reliées entre elles, ayant des intérêts, des lois, des gouvernements, des tarifs douaniers différents, ont été rassemblées, fondues en une seule nation, sous un seul gouvernement, une seule loi, un seul tarif douanier et un seul intérêt national de classe."
  ],
  "ch1_p25": [
    "La Bourgeoisie, depuis son avènement, à peine séculaire, a créé des forces productives plus variées et plus colossales que toutes les générations passées prises ensemble.",
    "La subjugation des forces de la nature, les machines, l’application de la chimie à l’industrie et à l’agriculture, la navigation à vapeur, les chemins de fer, les télégraphes électriques, le défrichement de continents entiers, la canalisation des rivières, des populations entières sortant de terre comme par enchantement, — quel siècle antérieur a soupçonné que de pareilles forces productives dormaient dans le sein du travail social ?"
  ],
  "ch1_p26": [
    "Voici donc ce que nous avons vu : les moyens de production et d’échange sur la base desquels s’est édifiée la Bourgeoisie ont été créés dans le sein de la société féodale.",
    "À un certain degré du développement de ces moyens de production et d’échange, les conditions dans lesquelles la société féodale produisait et échangeait, l’organisation féodale de l’agriculture et de la manufacture, en un mot les rapports de propriété féodaux cessèrent de correspondre aux forces productives en plein développement.",
    "Ils entravaient la production au lieu de la favoriser.",
    "Ils se transformèrent en autant de chaînes.",
    "Il fallait briser ces chaînes ; elles furent brisées.",
    "À leur place s’éleva la libre concurrence, avec une constitution sociale et politique appropriée, avec la suprématie économique et politique de la classe bourgeoise."
  ],
  "ch1_p27": [
    "Sous nos yeux il se produit un phénomène analogue.",
    "La société bourgeoise moderne, qui a mis en mouvement de si puissants moyens de production et d’échange, ressemble au magicien qui ne sait plus dominer les puissances infernales qu’il a évoquées.",
    "Depuis trente ans au moins, l’histoire de l’industrie et du commerce n’est que l’histoire de la révolte des forces productives contre les rapports de propriété qui sont les conditions d’existence de la Bourgeoisie et de son règne."
  ],
  "ch1_p28": [
    "Il suffit de mentionner les crises commerciales qui, par leur retour périodique, mettent de plus en plus en question l’existence de la société bourgeoise.",
    "Chaque crise détruit régulièrement non seulement une masse de produits déjà créés, mais encore une grande partie des forces productives elles-mêmes.",
    "Une épidémie, qui, à toute autre époque, eût semblé un paradoxe, s’abat sur la société, — l’épidémie de la surproduction.",
    "La société se trouve subitement rejetée dans un état de barbarie momentanée ; on dirait qu’une famine, qu’une guerre d’extermination lui coupent tous les moyens de subsistance ; l’industrie et le commerce semblent annihilés.",
    "Et pourquoi ?",
    "Parce que la société a trop de civilisation, trop de moyens de subsistance, trop d’industrie, trop de commerce.",
    "Les forces productives dont elle dispose ne favorisent plus le développement des conditions de la propriété bourgeoise ; au contraire, elles sont devenues trop puissantes pour ces conditions qui se tournent en entraves ; et toutes les fois que les forces productives sociales s’affranchissent de ces entraves, elles précipitent dans le désordre la société tout entière et menacent l’existence de la propriété bourgeoise."
  ],
  "ch1_p29": [
    "Comment la Bourgeoisie surmonte-t-elle ces crises ?",
    "D’une part par la destruction forcée d’une masse de forces productives ; d’autre part par la conquête de marchés nouveaux et l’exploitation plus parfaite des anciens marchés.",
    "Par quel moyen ?",
    "En préparant des crises plus générales et plus formidables et en diminuant les moyens de les prévenir."
  ],
  "ch1_p30": [
    "Les armes dont la Bourgeoisie s’est servie pour abattre la féodalité se retournent aujourd’hui contre la Bourgeoisie elle-même."
  ],
  "ch1_p31": [
    "Mais la Bourgeoisie n’a pas seulement forgé les armes qui doivent lui donner la mort ; elle a produit aussi les hommes qui doivent manier ces armes, — les ouvriers modernes, les Prolétaires."
  ],
  "ch1_p32": [
    "Avec le développement de la Bourgeoisie, c’est-à-dire du capital, se développe le Prolétariat, la classe des ouvriers modernes qui ne vivent qu’à la condition de trouver du travail et qui n’en trouvent plus dès que leur travail cesse d’agrandir le capital.",
    "Les ouvriers, contraints de se vendre au jour le jour, sont une marchandise, un article de commerce comme un autre ; ils sont exposés, par conséquent, à toutes les vicissitudes de la concurrence, à toutes les fluctuations du marché."
  ],
  "ch1_p33": [
    "L’introduction des machines et la division du travail dépouillent le travail de l’ouvrier de son caractère individuel et lui enlèvent tout attrait.",
    "Le producteur devient un simple appendice de la machine ; on n’exige de lui que l’opération la plus simple, la plus monotone, la plus vite apprise.",
    "Par suite, le coût de production de l’ouvrier se réduit presque entièrement au prix des moyens de subsistance dont il a besoin pour s’entretenir et perpétuer sa race.",
    "Or, le prix d’une marchandise, et par conséquent le prix du travail, est égal à son coût de production.",
    "À mesure donc que le travail devient plus répugnant, le salaire diminue.",
    "Bien plus, la somme de travail s’accroît avec le développement des machines et de la division du travail, soit par la prolongation de la journée de travail, soit par l’accélération du mouvement des machines."
  ],
  "ch1_p34": [
    "L’industrie moderne a transformé le petit atelier de l’artisan patriarcal en la grande fabrique du capitaliste industriel.",
    "Des masses d’ouvriers, entassés dans la fabrique, sont organisés militairement.",
    "Simples soldats de l’armée industrielle, ils sont placés sous la surveillance d’une hiérarchie complète d’officiers et de sous-officiers.",
    "Ils ne sont pas seulement les esclaves de la classe bourgeoise, de l’État bourgeois, mais ils sont encore, chaque jour, à chaque heure, les esclaves de la machine, du contremaître, et surtout du bourgeois fabricant lui-même.",
    "Ce despotisme est d’autant plus mesquin, plus odieux, plus exaspérant qu’il proclame plus ouvertement le profit comme étant son but unique."
  ],
  "ch1_p35": [
    "Moins le travail exige d’habileté et de force, c’est-à-dire plus l’industrie moderne progresse, et plus le travail des hommes est supplanté par celui des femmes et des enfants.",
    "Les distinctions d’âge et de sexe n’ont plus de valeur sociale pour la classe ouvrière.",
    "Il n’y a plus que des instruments de travail dont le prix varie suivant l’âge et le sexe."
  ],
  "ch1_p36": [
    "Une fois que l’ouvrier a subi l’exploitation du fabricant et qu’il a reçu son salaire en argent comptant, il devient la proie d’autres membres de la bourgeoisie, du propriétaire, du boutiquier, du prêteur sur gages."
  ],
  "ch1_p37": [
    "La petite Bourgeoisie, les petits industriels, les commerçants, les petits rentiers, les artisans et les paysans, tombent dans le prolétariat ; d’une part, parce que leurs petits capitaux ne leur permettant pas d’employer les procédés de la grande industrie, ils succombent dans leur concurrence avec les grands capitalistes ; d’autre part, parce que leur habileté spéciale est dépréciée par les nouveaux modes de production.",
    "De sorte que le Prolétariat se recrute dans toutes les classes de la population."
  ],
  "ch1_p38": [
    "Le Prolétariat passe par différentes phases d’évolution.",
    "Sa lutte contre la Bourgeoisie commence dès sa naissance."
  ],
  "ch1_p39": [
    "D’abord la lutte est engagée par des ouvriers isolés, ensuite par les ouvriers d’une même fabrique, enfin par les ouvriers d’une même branche d’industrie, en un même lieu, contre le bourgeois qui les exploite directement.",
    "Ils ne dirigent pas seulement leurs attaques contre les rapports bourgeois de production ; ils les dirigent contre les instruments de production eux-mêmes : ils détruisent les marchandises étrangères qui leur font concurrence, brisent les machines, brûlent les fabriques et s’efforcent de reconquérir la position perdue de l’artisan du moyen âge."
  ],
  "ch1_p40": [
    "À ce moment du développement, le Prolétariat forme une masse disséminée à travers le pays et émiettée par la concurrence.",
    "Si parfois les ouvriers s’unissent pour agir en masse, cette action n’est pas encore le résultat de leur propre union, mais de celle de la Bourgeoisie qui, pour atteindre ses fins politiques, doit mettre en branle le prolétariat tout entier, et qui, pour le moment, en a encore le pouvoir."
  ],
  "ch1_p41": [
    "Or l’industrie, en se développant, non seulement grossit le nombre des prolétaires, mais elle les concentre en masses plus grandes ; leur force grandit et ils en acquièrent une plus grande conscience.",
    "Les intérêts, les conditions d’existence se nivellent de plus en plus au sein du prolétariat, car la machine efface de plus en plus les différences de travail et réduit presque partout le salaire à un niveau également bas."
  ],
  "ch1_p42": [
    "Parfois les ouvriers triomphent ; mais c’est un triomphe éphémère.",
    "Le véritable résultat de leurs luttes est moins le succès immédiat que l’union toujours plus étendue des travailleurs.",
    "Cette union est facilitée par le développement des voies de communication qui permettent aux ouvriers de localités différentes de se mettre en relation.",
    "Or, il suffit de cette prise de contact pour centraliser les nombreuses luttes locales, qui partout ont le même caractère, en une lutte nationale, en une lutte de classes.",
    "Mais toute lutte de classes est une lutte politique, et l’union que les bourgeois du moyen âge mettaient des siècles à établir avec leurs chemins vicinaux, les prolétaires modernes la réalisent en quelques années grâce aux chemins de fer.",
    "Mais toute lutte de classes est une lutte politique, et l’union que les bourgeois du moyen âge mettaient des siècles à établir avec leurs chemins vicinaux, les prolétaires modernes la réalisent en quelques années grâce aux chemins de fer."
  ],
  "ch1_p43": [
    "L’organisation du Prolétariat en classe, et par suite en parti politique, est sans cesse détruite par la concurrence entre les ouvriers eux-mêmes.",
    "Mais elle renaît toujours, plus forte, plus ferme, plus formidable.",
    "Elle profite des divisions intestines des bourgeois pour les contraindre à reconnaître par une loi certains intérêts particuliers de la classe ouvrière : par exemple, la loi des dix heures de travail en Angleterre.",
    "Elle profite des divisions intestines des bourgeois pour les contraindre à reconnaître par une loi certains intérêts particuliers de la classe ouvrière : par exemple, la loi des dix heures de travail en Angleterre.",
    "Elle profite des divisions intestines des bourgeois pour les contraindre à reconnaître par une loi certains intérêts particuliers de la classe ouvrière : par exemple, la loi des dix heures de travail en Angleterre.",
    "Elle profite des divisions intestines des bourgeois pour les contraindre à reconnaître par une loi certains intérêts particuliers de la classe ouvrière : par exemple, la loi des dix heures de travail en Angleterre."
  ],
  "ch1_p44": [
    "En général, les collisions dans la vieille société favorisent de diverses manières le développement du prolétariat.",
    "La bourgeoisie vit dans un état de guerre perpétuel : d’abord contre l’aristocratie, puis contre ces fractions de la bourgeoisie même dont les intérêts entrent en contradiction avec le progrès de l’industrie, et toujours contre la bourgeoisie de tous les pays étrangers.",
    "Dans toutes ces luttes, elle se voit forcée de faire appel au prolétariat, de réclamer son aide et de l’entraîner ainsi dans le mouvement politique.",
    "Elle transmet donc au prolétariat des éléments de son éducation politique, c’est-à-dire des armes contre elle-même."
  ],
  "ch1_p45": [
    "De plus, ainsi que nous venons de le voir, des fractions entières de la classe régnante sont précipitées par le progrès de l’industrie dans le prolétariat, ou sont menacées, tout au moins, dans leurs conditions d’existence.",
    "Elles apportent au prolétariat de nombreux éléments de progrès.",
    "Enfin au moment où la lutte des classes approche de l’heure décisive, le processus de dissolution de la classe régnante, de la société tout entière, prend un caractère si violent et si âpre qu’une fraction de la classe régnante s’en détache et se rallie à la classe révolutionnaire, à la classe qui représente l’avenir.",
    "De même que jadis, une partie de la noblesse se rangea du côté de la Bourgeoisie, de nos jours une partie de la Bourgeoisie fait cause commune avec le prolétariat, notamment cette partie des idéologues bourgeois parvenue à l’intelligence théorique du mouvement historique dans son ensemble."
  ],
  "ch1_p46": [
    "De plus, ainsi que nous venons de le voir, des fractions entières de la classe dominante sont précipitées dans le prolétariat par le progrès de l'industrie.",
    "Elles apportent ainsi au prolétariat une masse d'éléments d'émancipation et d'éducation."
  ],
  "ch1_p47": [
    "Enfin, quand la lutte des classes approche de l'heure décisive, le processus de décomposition de la classe dominante prend un caractère si aigu qu'une petite fraction de cette classe s'en détache et se rallie à la classe révolutionnaire.",
    "De même qu'autrefois une partie de la noblesse passa à la bourgeoisie, de nos jours une partie de la bourgeoisie passe au prolétariat, notamment ceux des idéologues bourgeois parvenus à l'intelligence théorique de l'ensemble du mouvement historique."
  ],
  "ch1_p48": [
    "De toutes les classes qui à l’heure présente se trouvent face à face avec la Bourgeoisie, le Prolétariat seul est la classe vraiment révolutionnaire.",
    "Les autres classes périclitent et périssent avec la grande industrie ; le Prolétariat, au contraire, est son produit tout spécial."
  ],
  "ch1_p49": [
    "La classe moyenne, les petits fabricants, les détaillants, les paysans combattent la Bourgeoisie, parce qu’elle compromet leur existence en tant que classe moyenne.",
    "Ils ne sont donc pas révolutionnaires, mais conservateurs ; qui plus est, ils sont réactionnaires ; ils demandent que l’histoire fasse machine en arrière.",
    "S’ils agissent révolutionnairement, c’est par crainte de tomber dans le Prolétariat : ils défendent alors leurs intérêts futurs et non leurs intérêts actuels ; ils abandonnent leur propre point de vue pour se placer à celui du Prolétariat.",
    "S’ils agissent révolutionnairement, c’est par crainte de tomber dans le Prolétariat : ils défendent alors leurs intérêts futurs et non leurs intérêts actuels ; ils abandonnent leur propre point de vue pour se placer à celui du Prolétariat."
  ],
  "ch1_p50": [
    "La voyoucratie des grandes villes, cette putréfaction passive, cette lie des couches les plus basses de la vieille société, est çà et là entraînée dans le mouvement par une révolution prolétarienne ; cependant, par toutes ses conditions d’existence, elle penche plutôt à se vendre à la réaction.",
    "La voyoucratie des grandes villes, cette putréfaction passive, cette lie des couches les plus basses de la vieille société, est çà et là entraînée dans le mouvement par une révolution prolétarienne ; cependant, par toutes ses conditions d’existence, elle penche plutôt à se vendre à la réaction.",
    "La voyoucratie des grandes villes, cette putréfaction passive, cette lie des couches les plus basses de la vieille société, est çà et là entraînée dans le mouvement par une révolution prolétarienne ; cependant, par toutes ses conditions d’existence, elle penche plutôt à se vendre à la réaction."
  ],
  "ch1_p51": [
    "Les conditions d’existence de la vieille société sont déjà détruites dans les conditions d’existence du prolétariat.",
    "Le prolétaire est sans propriété ; ses relations avec sa femme et ses enfants n’ont rien de commun avec celles de la famille bourgeoise.",
    "Le travail industriel moderne, qui implique la sujétion de l’ouvrier au capital, aussi bien en Angleterre qu’en France, en Amérique qu’en Allemagne, a dépouillé le prolétaire de tout caractère national."
  ],
  "ch1_p52": [
    "Toutes les classes précédentes qui avaient conquis le pouvoir ont essayé de consolider la situation déjà acquise en soumettant la société tout entière à leur mode d’appropriation.",
    "Les prolétaires ne peuvent s’emparer des forces productives sociales qu’en abolissant leur propre mode d’appropriation antérieur, et par suite tout le mode d’appropriation existant jusqu’ici.",
    "Les prolétaires n’ont rien à eux à préserver ; ils ont à détruire toute garantie privée, toute sécurité privée existantes."
  ],
  "ch1_p53": [
    "Tous les mouvements historiques ont été, jusqu’ici, des mouvements de minorités ou au profit de minorités.",
    "Le mouvement prolétarien est le mouvement spontané de l’immense majorité au profit de l’immense majorité."
  ],
  "ch1_p54": [
    "La lutte du Prolétariat contre la Bourgeoisie, bien qu’elle ne soit pas au fond une lutte nationale, en prend cependant tout d’abord la forme."
  ],
  "ch1_p55": [
    "En esquissant à grands traits les phases du développement prolétarien, nous avons retracé l’histoire de la guerre civile, plus ou moins occulte, qui déchire la société jusqu’à l’heure où cette guerre éclate en une révolution ouverte, et où le prolétariat établit les bases de sa domination par le renversement violent de la bourgeoisie.",
    "En esquissant à grands traits les phases du développement prolétarien, nous avons retracé l’histoire de la guerre civile, plus ou moins occulte, qui déchire la société jusqu’à l’heure où cette guerre éclate en une révolution ouverte, et où le prolétariat établit les bases de sa domination par le renversement violent de la bourgeoisie.",
    "En esquissant à grands traits les phases du développement prolétarien, nous avons retracé l’histoire de la guerre civile, plus ou moins occulte, qui déchire la société jusqu’à l’heure où cette guerre éclate en une révolution ouverte, et où le prolétariat établit les bases de sa domination par le renversement violent de la bourgeoisie.",
    "En esquissant à grands traits les phases du développement prolétarien, nous avons retracé l’histoire de la guerre civile, plus ou moins occulte, qui déchire la société jusqu’à l’heure où cette guerre éclate en une révolution ouverte, et où le prolétariat établit les bases de sa domination par le renversement violent de la bourgeoisie.",
    "En esquissant à grands traits les phases du développement prolétarien, nous avons retracé l’histoire de la guerre civile, plus ou moins occulte, qui déchire la société jusqu’à l’heure où cette guerre éclate en une révolution ouverte, et où le prolétariat établit les bases de sa domination par le renversement violent de la bourgeoisie."
  ],
  "ch1_p56": [
    "Toutes les sociétés antérieures, nous l’avons vu, ont reposé sur l’antagonisme de la classe oppressive et de la classe opprimée.",
    "Mais pour opprimer une classe il faut, au moins, pouvoir lui garantir les conditions d’existence qui lui permettent de vivre en esclave.",
    "Le serf, en pleine féodalité, parvenait à se faire membre de la Commune ; le bourgeois embryonnaire du moyen âge atteignait la position de bourgeois, sous le joug de l’absolutisme féodal."
  ],
  "ch1_p57": [
    "La condition essentielle d’existence et de suprématie pour la classe bourgeoise est l’accumulation de la richesse dans des mains privées, la formation et l’accroissement du capital ; la condition du capital est le travail salarié.",
    "Le travail salarié repose exclusivement sur la concurrence des ouvriers entre eux.",
    "Le progrès de l’industrie, dont la bourgeoisie est l’agent sans volonté et sans résistance, substitue à l’isolement des ouvriers par la concurrence leur union révolutionnaire par l’association.",
    "Le développement de la grande industrie sape sous les pieds de la Bourgeoisie le terrain même sur lequel elle a bâti son système de production et d’appropriation.",
    "La Bourgeoisie produit avant tout ses propres fossoyeurs.",
    "Sa chute et la victoire du Prolétariat sont également inévitables."
  ]
};
